long long mod = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    int limit = 2 * n + 1;
    vector<bool> not_prime(limit + 2, false);
    not_prime[0] = not_prime[1] = true;
    vector<int> primes;

    for (int i = 0; i <= limit; ++i) {
        if (not_prime[i]) continue;
        primes.push_back(i);
        if ((long long)i * i <= limit) {
            for (int j = i * i; j <= limit; j += i) {
                not_prime[j] = true;
            }
        }
    }

    auto choose_mod = [&](int m, int k, long long mod_val) -> long long {
        int n = min(k, m - k);
        vector<int> factors(primes.size(), 0);
        for (size_t pos = 0; pos < primes.size(); ++pos) {
            int x = primes[pos];
            if (x > m) break;
            for (int i = x; i <= m; i += x) {
                if (i > n && i <= m - n) continue;
                int y = i;
                int c = 0;
                while (y % x == 0) {
                    y /= x;
                    ++c;
                }
                if (i <= n) {
                    factors[pos] -= c;
                } else {
                    factors[pos] += c;
                }
            }
        }
        long long result = 1;
        for (size_t pos = 0; pos < factors.size(); ++pos) {
            int cnt = factors[pos];
            int y = primes[pos];
            for (int i = 0; i < cnt; ++i) {
                result = (result * y) % mod_val;
            }
        }
        return result;
    };

    long long val = choose_mod(2 * n + 1, n, mod);
    long long ans = (2 * val - 1) % mod;
    if (ans < 0) ans += mod;
    cout << ans << '\n';

    return 0;
}

